import json
from typing import List, Dict, Any
from collections import defaultdict
import math


class RecommendationEngine:
    """
    Hybrid recommendation system:
    - Content-based: TF-IDF on content tags + user preferences
    - Collaborative: User-item interaction matrix (implicit feedback)
    """

    def __init__(self, interactions: List[Dict[str, Any]], contents: List[Dict[str, Any]]):
        self.interactions = interactions  # [{userId, contentId, action, timestamp}]
        self.contents = contents          # [{id, tags, region, type, ...}]
        self.user_profiles = self._build_user_profiles()
        self.content_vectors = self._build_content_vectors()

    def _build_user_profiles(self) -> Dict[str, Dict[str, float]]:
        """Build user preference vectors from interactions."""
        user_prefs = defaultdict(lambda: defaultdict(float))
        action_weights = {'view': 1.0, 'like': 2.0, 'share': 3.0}
        for interaction in self.interactions:
            uid = interaction['userId']
            cid = interaction['contentId']
            weight = action_weights.get(interaction['action'], 0.5)
            # Find content tags
            content = next((c for c in self.contents if c['id'] == cid), {})
            for tag in content.get('tags', []):
                user_prefs[uid][tag] += weight
            region = content.get('region')
            if region:
                user_prefs[uid][f"region:{region}"] += weight
        # Normalize
        for uid in user_prefs:
            total = sum(user_prefs[uid].values())
            if total > 0:
                for tag in user_prefs[uid]:
                    user_prefs[uid][tag] /= total
        return dict(user_prefs)

    def _build_content_vectors(self) -> Dict[str, Dict[str, float]]:
        """Build TF-IDF-like vectors for content."""
        content_vectors = {}
        all_tags = set()
        for c in self.contents:
            all_tags.update(c.get('tags', []))
            region = c.get('region')
            if region:
                all_tags.add(f"region:{region}")
        # Simple binary vector (can be upgraded to TF-IDF)
        for c in self.contents:
            vec = {tag: 1.0 for tag in c.get('tags', [])}
            region = c.get('region')
            if region:
                vec[f"region:{region}"] = 1.0
            content_vectors[c['id']] = vec
        return content_vectors

    def recommend(self, user_id: str, n: int = 10) -> List[Dict[str, Any]]:
        """Return top-N content recommendations for user."""
        if user_id not in self.user_profiles:
            # Fallback: return popular content
            return self._popular(n)

        user_vec = self.user_profiles[user_id]
        scores = []
        for cid, cvec in self.content_vectors.items():
            # Cosine similarity
            dot = sum(user_vec.get(tag, 0) * cvec.get(tag, 0) for tag in cvec)
            user_norm = math.sqrt(sum(v**2 for v in user_vec.values()))
            content_norm = math.sqrt(sum(v**2 for v in cvec.values()))
            if user_norm * content_norm > 0:
                score = dot / (user_norm * content_norm)
            else:
                score = 0
            scores.append((cid, score))

        scores.sort(key=lambda x: x[1], reverse=True)
        top_ids = [cid for cid, _ in scores[:n]]
        return [c for c in self.contents if c['id'] in top_ids]

    def _popular(self, n: int) -> List[Dict[str, Any]]:
        """Fallback: return most interacted content."""
        counts = defaultdict(int)
        for interaction in self.interactions:
            counts[interaction['contentId']] += 1
        top_ids = sorted(counts, key=counts.get, reverse=True)[:n]
        return [c for c in self.contents if c['id'] in top_ids]


