from flask import Flask, request, jsonify
from flask_cors import CORS
from flask_socketio import SocketIO, emit
from pymongo import MongoClient
from bson import ObjectId
import jwt
import datetime
import hashlib
import os
from datetime import timedelta

app = Flask(__name__)
CORS(app)
socketio = SocketIO(app, cors_allowed_origins="*")

# Configuration
app.config['SECRET_KEY'] = os.getenv('SECRET_KEY', 'culturalconnect-secret-key')
MONGO_URI = os.getenv('MONGO_URI', 'mongodb://localhost:27017/culturalconnect')
client = MongoClient(MONGO_URI)
db = client.culturalconnect

# Collections
users = db.users
content = db.content
interactions = db.interactions
recommendations = db.recommendations

# Helper functions
def hash_password(password):
    return hashlib.sha256(password.encode()).hexdigest()

def generate_token(user_id):
    payload = {
        'user_id': str(user_id),
        'exp': datetime.datetime.utcnow() + timedelta(days=7)
    }
    return jwt.encode(payload, app.config['SECRET_KEY'], algorithm='HS256')

def decode_token(token):
    try:
        return jwt.decode(token, app.config['SECRET_KEY'], algorithms=['HS256'])
    except:
        return None

# User Authentication Endpoints
@app.route('/api/auth/register', methods=['POST'])
def register():
    data = request.json
    if users.find_one({'email': data['email']}):
        return jsonify({'error': 'Email already registered'}), 400
    user = {
        'name': data['name'],
        'email': data['email'],
        'password': hash_password(data['password']),
        'preferences': data.get('preferences', []),
        'created_at': datetime.datetime.utcnow()
    }
    result = users.insert_one(user)
    token = generate_token(result.inserted_id)
    return jsonify({'token': token, 'user': {'id': str(result.inserted_id), 'name': data['name'], 'email': data['email']}}), 201

@app.route('/api/auth/login', methods=['POST'])
def login():
    data = request.json
    user = users.find_one({'email': data['email']})
    if not user or user['password'] != hash_password(data['password']):
        return jsonify({'error': 'Invalid credentials'}), 401
    token = generate_token(user['_id'])
    return jsonify({'token': token, 'user': {'id': str(user['_id']), 'name': user['name'], 'email': user['email']}})

# Content Management Endpoints
@app.route('/api/content', methods=['GET'])
def get_content():
    category = request.args.get('category')
    query = {}
    if category:
        query['category'] = category
    items = list(content.find(query, {'_id': 1, 'title': 1, 'category': 1, 'description': 1, 'media_url': 1, 'source': 1}))
    for item in items:
        item['_id'] = str(item['_id'])
    return jsonify(items)

@app.route('/api/content/<content_id>', methods=['GET'])
def get_content_by_id(content_id):
    item = content.find_one({'_id': ObjectId(content_id)})
    if not item:
        return jsonify({'error': 'Content not found'}), 404
    item['_id'] = str(item['_id'])
    return jsonify(item)

# Interaction & Recommendation System
@app.route('/api/interactions', methods=['POST'])
def log_interaction():
    data = request.json
    interaction = {
        'user_id': ObjectId(data['user_id']),
        'content_id': ObjectId(data['content_id']),
        'type': data['type'],  # 'view', 'like', 'share', 'comment'
        'timestamp': datetime.datetime.utcnow()
    }
    interactions.insert_one(interaction)
    return jsonify({'status': 'success'}), 201

@app.route('/api/recommendations', methods=['GET'])
def get_recommendations():
    user_id = request.args.get('user_id')
    if not user_id:
        return jsonify({'error': 'user_id required'}), 400

    # Simple collaborative filtering: find users with similar preferences
    user = users.find_one({'_id': ObjectId(user_id)})
    if not user:
        return jsonify({'error': 'User not found'}), 404

    user_prefs = set(user.get('preferences', []))
    if not user_prefs:
        # Fallback: return popular content
        popular = list(content.aggregate([
            {'$group': {'_id': '$_id', 'score': {'$sum': 1}}},
            {'$sort': {'score': -1}},
            {'$limit': 10}
        ]))
        return jsonify([str(p['_id']) for p in popular])

    # Find similar users
    similar_users = list(users.aggregate([
        {'$project': {'_id': 1, 'prefs': {'$ifNull': ['$preferences', []]}}},
        {'$addFields': {'match': {'$size': {'$setIntersection': ['$prefs', list(user_prefs)]}}}},
        {'$match': {'match': {'$gt': 0}}},
        {'$sort': {'match': -1}},
        {'$limit': 5}
    ]))

    # Aggregate content liked by similar users
    similar_user_ids = [u['_id'] for u in similar_users]
    liked_content = list(interactions.aggregate([
        {'$match': {'user_id': {'$in': similar_user_ids}, 'type': {'$in': ['like', 'share']}}},
        {'$group': {'_id': '$content_id', 'score': {'$sum': 1}}},
        {'$sort': {'score': -1}},
        {'$limit': 10}
    ]))

    return jsonify([str(c['_id']) for c in liked_content])

# WebSocket Chat Feature
@socketio.on('connect')
def handle_connect():
    emit('message', {'data': 'Connected to CulturalConnect chat'})

@socketio.on('join_room')
def handle_join_room(data):
    room = data['room']
    emit('message', {'data': f'Joined room {room}'}, room=room)

@socketio.on('send_message')
def handle_send_message(data):
    room = data['room']
    message = {
        'user_id': data['user_id'],
        'content': data['content'],
        'timestamp': datetime.datetime.utcnow().isoformat()
    }
    emit('receive_message', message, room=room)

